const listTimelineEntries = `-- name: ListTimelineEntries :many
SELECT d.document_id AS entry_id, 'note' AS kind, d.created_at AS at,
       d.encounter_id, d.title, d.confidentiality, d.authored_by
FROM clinical.document d
WHERE d.tenant_id = $2 AND d.patient_id = $3
  AND d.created_at >= $4::timestamptz AND d.created_at < $5::timestamptz
  AND d.status <> 'entered_in_error'

UNION ALL

SELECT o.observation_id AS entry_id, 'observation' AS kind, o.effective_at AS at,
       COALESCE(o.encounter_id, '00000000-0000-0000-0000-000000000000'::uuid),
       o.code_display AS title, 'normal' AS confidentiality, o.recorded_by AS authored_by
FROM clinical.observation o
WHERE o.tenant_id = $2 AND o.patient_id = $3
  AND o.effective_at >= $4::timestamptz AND o.effective_at < $5::timestamptz
  AND o.status NOT IN ('cancelled', 'entered_in_error')

UNION ALL

SELECT p.procedure_id AS entry_id, 'procedure' AS kind,
       COALESCE(p.performed_start, p.recorded_at) AS at,
       p.encounter_id, p.code_display AS title, 'normal' AS confidentiality,
       p.recorded_by AS authored_by
FROM clinical.procedure p
WHERE p.tenant_id = $2 AND p.patient_id = $3
  AND COALESCE(p.performed_start, p.recorded_at) >= $4::timestamptz
  AND COALESCE(p.performed_start, p.recorded_at) < $5::timestamptz
  AND p.status <> 'entered_in_error'

UNION ALL

SELECT a.allergy_id AS entry_id, 'allergy' AS kind, a.recorded_at AS at,
       COALESCE(a.encounter_id, '00000000-0000-0000-0000-000000000000'::uuid),
       a.substance_display AS title, 'normal' AS confidentiality,
       a.recorded_by AS authored_by
FROM clinical.allergy a
WHERE a.tenant_id = $2 AND a.patient_id = $3
  AND a.recorded_at >= $4::timestamptz AND a.recorded_at < $5::timestamptz
  AND a.verification <> 'entered_in_error'

ORDER BY at DESC, entry_id
LIMIT $1
`

type ListTimelineEntriesParams struct {
	PageLimit int32
	TenantID  uuid.UUID
	PatientID uuid.UUID
	FromAt    pgtype.Timestamptz
	UntilAt   pgtype.Timestamptz
}

type ListTimelineEntriesRow struct {
	EntryID         uuid.UUID
	Kind            string
	At              pgtype.Timestamptz
	EncounterID     uuid.UUID
	Title           string
	Confidentiality string
	AuthoredBy      string
}

// The clinical half of the longitudinal timeline (SRS-ENC-011).
//
// One query rather than five round trips, because the timeline is the screen
// everybody keeps open. Confidentiality is returned rather than filtered here:
// the encounter context applies the filter once, on the way out, so one rule
// governs every contributing source.
func (q *Queries) ListTimelineEntries(ctx context.Context, arg ListTimelineEntriesParams) ([]ListTimelineEntriesRow, error) {
	rows, err := q.db.Query(ctx, listTimelineEntries,
		arg.PageLimit,
		arg.TenantID,
		arg.PatientID,
		arg.FromAt,
		arg.UntilAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTimelineEntriesRow{}
	for rows.Next() {
		var i ListTimelineEntriesRow
		if err := rows.Scan(
			&i.EntryID,
			&i.Kind,
			&i.At,
			&i.EncounterID,
			&i.Title,
			&i.Confidentiality,
			&i.AuthoredBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUnacknowledgedCriticalResults = `-- name: ListUnacknowledgedCriticalResults :many
SELECT o.observation_id, o.tenant_id, o.patient_id, o.encounter_id, o.code_system,
       o.code_version, o.code, o.code_display, o.value_quantity, o.value_unit,
       o.value_text, o.value_code_system, o.value_code, o.value_code_display,
       o.reference_low, o.reference_high, o.reference_text, o.interpretation,
       o.interpretation_source, o.status, o.effective_at, o.issued_at,
       o.performer_id, o.device_id, o.source_system, o.note, o.amends_id,
       o.recorded_by, o.recorded_at, o.version
FROM clinical.observation o
WHERE o.tenant_id = $1
  AND o.interpretation IN ('critical_high', 'critical_low')
  AND o.status NOT IN ('cancelled', 'entered_in_error')
  AND NOT EXISTS (
      SELECT 1 FROM clinical.critical_acknowledgement a
      WHERE a.tenant_id = o.tenant_id AND a.observation_id = o.observation_id
  )
ORDER BY o.issued_at NULLS FIRST, o.observation_id
LIMIT $2
`

type ListUnacknowledgedCriticalResultsParams struct {
	TenantID  uuid.UUID
	PageLimit int32
}

// The worklist that must reach a clinician now (SRS-CLN-012).
func (q *Queries) ListUnacknowledgedCriticalResults(ctx context.Context, arg ListUnacknowledgedCriticalResultsParams) ([]ClinicalObservation, error) {
	rows, err := q.db.Query(ctx, listUnacknowledgedCriticalResults, arg.TenantID, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ClinicalObservation{}
	for rows.Next() {
		var i ClinicalObservation
		if err := rows.Scan(
			&i.ObservationID,
			&i.TenantID,
			&i.PatientID,
			&i.EncounterID,
			&i.CodeSystem,
			&i.CodeVersion,
			&i.Code,
			&i.CodeDisplay,
			&i.ValueQuantity,
			&i.ValueUnit,
			&i.ValueText,
			&i.ValueCodeSystem,
			&i.ValueCode,
			&i.ValueCodeDisplay,
			&i.ReferenceLow,
			&i.ReferenceHigh,
			&i.ReferenceText,
			&i.Interpretation,
			&i.InterpretationSource,
			&i.Status,
			&i.EffectiveAt,
			&i.IssuedAt,
			&i.PerformerID,
			&i.DeviceID,
			&i.SourceSystem,
			&i.Note,
			&i.AmendsID,
			&i.RecordedBy,
			&i.RecordedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const respondToCDSAlert = `-- name: RespondToCDSAlert :execrows
UPDATE clinical.cds_alert
SET outcome = $1, override_code = $2,
    override_reason = $3, responded_by = $4,
    responded_at = $5
WHERE tenant_id = $6
  AND alert_id = $7
  AND outcome = 'pending'
`

type RespondToCDSAlertParams struct {
	Outcome        string
	OverrideCode   string
	OverrideReason string
	RespondedBy    string
	RespondedAt    pgtype.Timestamptz
	TenantID       uuid.UUID
	AlertID        uuid.UUID
}

// Guarded on still being pending: answering twice would let a second click
// rewrite the first clinician's stated reason.
func (q *Queries) RespondToCDSAlert(ctx context.Context, arg RespondToCDSAlertParams) (int64, error) {
	result, err := q.db.Exec(ctx, respondToCDSAlert,
		arg.Outcome,
		arg.OverrideCode,
		arg.OverrideReason,
		arg.RespondedBy,
		arg.RespondedAt,
		arg.TenantID,
		arg.AlertID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

