const upsertSmartPhrase = `-- name: UpsertSmartPhrase :exec
INSERT INTO clinical.smart_phrase (
    phrase_id, tenant_id, owner_id, shortcut, expansion, created_at, updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6,
    $7
)
ON CONFLICT (tenant_id, owner_id, shortcut)
DO UPDATE SET expansion = EXCLUDED.expansion, updated_at = EXCLUDED.updated_at
`

type UpsertSmartPhraseParams struct {
	PhraseID  uuid.UUID
	TenantID  uuid.UUID
	OwnerID   string
	Shortcut  string
	Expansion string
	CreatedAt pgtype.Timestamptz
	UpdatedAt pgtype.Timestamptz
}

func (q *Queries) UpsertSmartPhrase(ctx context.Context, arg UpsertSmartPhraseParams) error {
	_, err := q.db.Exec(ctx, upsertSmartPhrase,
		arg.PhraseID,
		arg.TenantID,
		arg.OwnerID,
		arg.Shortcut,
		arg.Expansion,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}
